//! Scale factors derived from unit strings, and the way a chain of ZoomMaps
//! combines them, checked bit-for-bit against the C library.
//!
//! `unit_mapper_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/unit_mapper_probe.c`, which records:
//!
//! - `UNIT_CASES`: `astConvert` between two one-axis Frames that have
//!   ActiveUnit set, so the units Mapping comes from `astUnitMapper`
//!   (frame.c SubFrame).
//! - `SPEC_CASES`: `astConvert` between two SpecFrames that differ only in
//!   Unit. The result is a chain of forward and inverted unit ZoomMaps that
//!   zoommap.c `MapMerge` folds into one factor.
//! - `ZOOM_CASES`: `astSimplify` of a series CmpMap of two or three
//!   ZoomMaps, each possibly inverted.
//!
//! Each Mapping is applied to the same values in both directions.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "unit_mapper_oracle/cases.rs"]
mod cases;

use ast_core::coords::PointSet;
use ast_core::frames::{BasicFrameBuilder, Frame, FrameRef, SpecFrame, SpecSystem};
use ast_core::mappings::{CmpMap, Composition, DynMapping, Mapping, ZoomMap};

/// The images of `cases::VALUES` under `map`, forward and inverse.
fn images(map: &dyn Mapping) -> (Vec<f64>, Vec<f64>) {
    let pts = PointSet::from_rows(cases::VALUES.map(|v| [v]));
    let apply = |forward| {
        let out = map.transform(&pts, forward).unwrap();
        (0..cases::VALUES.len()).map(|i| out.point(i)[0]).collect()
    };
    (apply(true), apply(false))
}

/// Compare `map` with C's images, recording a failure for `what`.
fn check(what: String, map: &dyn Mapping, want: &cases::Images, failures: &mut Vec<String>) {
    let (fwd, inv) = images(map);
    if fwd != want.0 || inv != want.1 {
        failures.push(format!(
            "{what}: forward {fwd:?} inverse {inv:?}, C gives forward {:?} inverse {:?}",
            want.0, want.1
        ));
    }
}

/// The Mapping from `from` to `to` that `convert_to` finds.
fn convert(from: &dyn Frame, to: &dyn Frame) -> DynMapping {
    from.snapshot()
        .convert_to(to.snapshot().as_mut(), &[])
        .unwrap()
        .expect("a conversion")
        .mapping(FrameRef::Base, FrameRef::Current)
        .unwrap()
}

#[test]
fn unit_mappings_match_the_c_library() {
    let frame = |unit: &str| {
        let mut f = BasicFrameBuilder::new(1).unit(1, unit).build().unwrap();
        f.set_active_unit(true);
        f
    };
    let mut failures = Vec::new();
    for (from, to, want) in cases::UNIT_CASES {
        let map = convert(&frame(from), &frame(to));
        check(format!("{from} -> {to}"), map.as_ref(), want, &mut failures);
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn spec_frame_unit_changes_match_the_c_library() {
    let frame = |system: &str, unit: &str| {
        let mut f = SpecFrame::new(SpecSystem::parse(system).unwrap());
        f.set_unit(1, unit).unwrap();
        f
    };
    let mut failures = Vec::new();
    for (system, from, to, want) in cases::SPEC_CASES {
        let map = convert(&frame(system, from), &frame(system, to));
        check(
            format!("{system} {from} -> {to}"),
            map.as_ref(),
            want,
            &mut failures,
        );
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn zoom_map_chains_simplify_as_the_c_library_does() {
    let zoom = |z: f64, inverted: bool| -> DynMapping {
        let mut m = ZoomMap::new(1, z).unwrap();
        if inverted {
            m.invert();
        }
        Box::new(m)
    };
    let mut failures = Vec::new();
    for (factors, inverted, want) in cases::ZOOM_CASES {
        // Nest as the probe does: ((z1 z2) z3).
        let mut chain = zoom(factors[0], inverted[0]);
        for (&z, &inv) in factors.iter().zip(inverted.iter()).skip(1) {
            chain = Box::new(CmpMap::new(chain, zoom(z, inv), Composition::Series).unwrap());
        }
        let simplified = chain.simplify().unwrap();
        check(
            format!("{factors:?} inverted {inverted:?}"),
            simplified.as_ref(),
            want,
            &mut failures,
        );
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
